  'preserves Supervisor review policy and archived assurance ($version, required=$required, session=$session)',
  async ({ version, required, session, accepted }) => {
    const f = await nativeSupervisorReviewFixture(version, required);
    const projection = await projectNativeSdkContinuation({
      run: f.run,
      state: f.run.state as NativePortableState,
      projectRoot: f.root,
    });
    expect(projection.pendingActions.at(-1)?.sessionRequirements).toMatchObject({
      independent: version === '2' || required,
      readOnly: true,
    });
    const output = {
      candidateCommit: f.candidateCommit,
      verdict: 'pass',
      evidence: {
        summary: 'Reviewed actual API behavior.',
        checks: ['api-check'],
        acceptance: [{ id: 'child:api', result: 'passed', reason: 'The API scenario passed.' }],
      },
      integrationChecks: [{ ...f.check, id: 'api-integration' }],
    };
    const operation = succeedLatestAction(
      f.runtime,
      f.run,
      output,
      f.root,
      'child-reviewed',
      session,
    );
    if (!accepted) {
      await expect(operation).rejects.toThrow(/required independent session/);
      expect((await f.runtime.inspect(f.run.runId)).actions.at(-1)).toMatchObject({
        stepId: 'supervisor.child.verifier',
        status: 'running',
      });
      return;
    }
    let run = await operation;
    for (const executorId of [
      'native-supervisor-integrate',
      'comet-native-checks',
      'native-supervisor-child-archive',
    ]) {
      run = await f.runtime.execute({
        runId: run.runId,
        actionId: run.actions.at(-1)!.id,
        executorId,
        context: { requestId: executorId, projectRoot: f.root },
      });
    }
    const receipt = run.outputs['supervisor.child.archive'].value as { archiveRef: string };
    const archived = parseYaml(
      await fs.readFile(
        path.join(f.childWorktree, 'docs/comet/archive', receipt.archiveRef, 'comet-state.yaml'),
        'utf8',
      ),
    );
    expect(archived.verification).toMatchObject({
      verifier_execution_ref: session,
      assurance: session === 'child-builder' ? 'self-reviewed' : 'skill-coordinated',
    });
  },
);

import { promises as fs, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import {
  hasGitlinksInIndex,
  nativeCheckInputFingerprint,
  nativeCheckInputSnapshot,
  nativeCheckInputGate,
  nativeCandidateInputGate,
  nativeGeneratedCheckInputSnapshot,
  nativeRawInputSnapshot,
} from '../../../domains/comet-native/native-portable-checks.js';
import * as gitCommands from '../../../platform/process/git.js';
import * as raceSafeRead from '../../../platform/fs/race-safe-read.js';
import { resolveWorkspaceRuntimeRoot } from '../../../domains/workflow-contract/workspace-runtime.js';
import { requireFileSymlink } from '../../helpers/file-symlink.js';

function git(root: string, ...args: string[]): string {
  return execFileSync('git', ['-C', root, ...args], { encoding: 'utf8' });
}

function fingerprintInput(projectRoot: string) {
  return {
    state: {
      builder_handoff: null,
      shape_confirmation_hash: null,
      acceptance: [],
    },
    projectRoot,
    plans: [],
  };
}

describe('Native check input fingerprint', () => {
  let root: string;

  beforeEach(async () => {
    root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-check-fingerprint-'));
    git(root, 'init', '--quiet');
    git(root, 'config', 'user.email', 'test@example.com');
    git(root, 'config', 'user.name', 'Test');
    await fs.writeFile(path.join(root, 'committed.txt'), 'committed\n');
    await fs.writeFile(path.join(root, 'large.bin'), 'x'.repeat(300 * 1024));
    git(root, 'add', '.');
    git(root, 'commit', '--quiet', '-m', 'baseline');
  });

  afterEach(async () => {
    vi.restoreAllMocks();
    await fs.rm(root, { recursive: true, force: true });
  });

  it('excludes only declared untracked test outputs and binds tracked files and undeclared generated inputs', async () => {
    await fs.writeFile(path.join(root, '.gitignore'), 'dist/\n');
    await fs.mkdir(path.join(root, 'dist/eval'), { recursive: true });
    await fs.writeFile(path.join(root, 'dist/eval/tracked.json'), 'tracked');
    await fs.writeFile(path.join(root, 'dist/app.js'), 'application');
    git(root, 'add', '-f', 'dist/eval/tracked.json');
    const before = await nativeRawInputSnapshot({ projectRoot: root, outputs: ['dist/eval'] });
    await fs.writeFile(path.join(root, 'dist/eval/trace.json'), 'trace');
    const after = await nativeRawInputSnapshot({ projectRoot: root, previous: before });
    expect(after.complete, after.diagnostics.join(';')).toBe(true);
    expect(after.contentHash).toBe(before.contentHash);
    expect(after.files.map((file) => file.path)).toContain('dist/eval/tracked.json');
    await fs.writeFile(path.join(root, 'dist/eval/tracked.json'), 'changed tracked');
    const tracked = await nativeRawInputSnapshot({ projectRoot: root, previous: after });
    expect(tracked.contentHash).not.toBe(after.contentHash);
    await fs.writeFile(path.join(root, 'dist/app.js'), 'changed application');
    const application = await nativeRawInputSnapshot({ projectRoot: root, previous: tracked });
    expect(application.contentHash).not.toBe(tracked.contentHash);
  });

  it('observes raw mixed-language and binary changes without a compiler and separates Git metadata', async () => {
    git(root, 'config', 'core.autocrlf', 'false');
    for (const ref of ['code.py', 'code.ts', 'code.unknown', 'README.md'])
      await fs.writeFile(path.join(root, ref), `${ref}\r\nnot necessarily valid syntax\r\n`);
    await fs.writeFile(path.join(root, 'bytes.bin'), Buffer.from([0, 255, 128]));
    const before = await nativeRawInputSnapshot({ projectRoot: root });
    expect(before.complete, before.diagnostics.join(';')).toBe(true);
    git(root, 'add', '.');
    const staged = await nativeRawInputSnapshot({ projectRoot: root });
    expect(staged.contentHash).toBe(before.contentHash);
    expect(staged.git).not.toEqual(before.git);
    git(root, 'reset', '--quiet');
    expect((await nativeRawInputSnapshot({ projectRoot: root })).contentHash).toBe(
      before.contentHash,
    );
    git(root, 'add', '.');
    git(root, 'commit', '--quiet', '-m', 'mixed input');
    git(root, 'commit', '--quiet', '--allow-empty', '-m', 'metadata only');
    expect((await nativeRawInputSnapshot({ projectRoot: root })).contentHash).toBe(
      before.contentHash,
    );
    await fs.writeFile(path.join(root, 'code.unknown'), 'changed content');
    expect((await nativeRawInputSnapshot({ projectRoot: root })).contentHash).not.toBe(
      before.contentHash,
    );
    await fs.unlink(path.join(root, 'code.py'));
    const deleted = await nativeRawInputSnapshot({ projectRoot: root });
    expect(deleted.complete, deleted.diagnostics.join(';')).toBe(true);
    expect(deleted.files.some((file) => file.path === 'code.py')).toBe(false);
  });

  it('reuses verified clean hashes but reads assume-unchanged edits with restored timestamps', async () => {
    const before = await nativeRawInputSnapshot({ projectRoot: root });
    expect(before.complete, before.diagnostics.join(';')).toBe(true);
    const probe = vi.spyOn(raceSafeRead, 'hashFileRaceSafe');
    const stable = await nativeRawInputSnapshot({ projectRoot: root, previous: before });
    expect(stable.complete, stable.diagnostics.join(';')).toBe(true);
    expect(stable.contentHash).toBe(before.contentHash);
    expect(probe.mock.calls.some(([file]) => file === path.join(root, 'large.bin'))).toBe(false);
    const target = path.join(root, 'committed.txt');
    const stat = await fs.stat(target);
    git(root, 'update-index', '--assume-unchanged', 'committed.txt');
    await fs.writeFile(target, 'different\n');
    await fs.utimes(target, stat.atime, stat.mtime);
    probe.mockClear();
    const edited = await nativeRawInputSnapshot({ projectRoot: root, previous: stable });
    expect(edited.complete, edited.diagnostics.join(';')).toBe(true);
    expect(edited.contentHash).not.toBe(before.contentHash);
    expect(probe.mock.calls.some(([file]) => file === path.join(root, 'committed.txt'))).toBe(true);
  });

  it('rejects a file changed after its read while another input is being captured', async () => {
    await fs.writeFile(path.join(root, 'a.unknown'), 'first');
    await fs.writeFile(path.join(root, 'b.unknown'), 'second');
    const original = raceSafeRead.hashFileRaceSafe;
    let release!: () => void;
    const firstRead = new Promise<void>((resolve) => {
      release = resolve;
    });
    vi.spyOn(raceSafeRead, 'hashFileRaceSafe').mockImplementation(async (...args) => {
      if (args[0] === path.join(root, 'b.unknown')) {
        await firstRead;
        await fs.writeFile(path.join(root, 'a.unknown'), 'later');
      }
      const result = await original(...args);
      if (args[0] === path.join(root, 'a.unknown')) release();
      return result;
    });
    const snapshot = await nativeRawInputSnapshot({ projectRoot: root });
    expect(snapshot.complete).toBe(false);
    expect(snapshot.diagnostics.join(';')).toContain('a.unknown');
    expect(await fs.readFile(path.join(root, 'a.unknown'), 'utf8')).toBe('later');
  });

  it.each([false, true])(
    'captures generated leaf metadata with bounded overlap and drains failures (failure=%s)',
    async (failure) => {
      await fs.writeFile(path.join(root, '.gitignore'), 'dist/\n');
      const directory = path.join(root, 'dist');
      await fs.mkdir(directory);
      const leaves = Array.from({ length: 32 }, (_, index) => path.join(directory, `${index}.bin`));
      await Promise.all(leaves.map((file, index) => fs.writeFile(file, `input ${index}`)));
      const selected = new Set(leaves);
      const firstReads = new Set<string>();
      const original = fs.lstat;
      let active = 0;
      let peak = 0;
      vi.spyOn(fs, 'lstat').mockImplementation((async (...args: Parameters<typeof fs.lstat>) => {
        const target = String(args[0]);
        if (!selected.has(target) || firstReads.has(target)) return original(...args);
        firstReads.add(target);
        active++;
        peak = Math.max(peak, active);
        try {
          await new Promise((resolve) => setTimeout(resolve, 5));
          if (failure && target === leaves[4]) throw new Error('fixture metadata unavailable');
          return await original(...args);
        } finally {
          active--;
        }
      }) as typeof fs.lstat);
      const snapshot = await nativeRawInputSnapshot({ projectRoot: root });
      expect(active).toBe(0);
      expect(peak).toBeGreaterThan(1);
      expect(peak).toBeLessThanOrEqual(16);
      expect(snapshot.complete, snapshot.diagnostics.join(';')).toBe(!failure);
      if (failure) {
        expect(snapshot.diagnostics.join(';')).toContain('metadata unavailable');
      } else {
        expect(firstReads.size).toBe(leaves.length);
        expect(snapshot.files.filter((file) => file.path.startsWith('dist/'))).toHaveLength(
          leaves.length,
        );
        await fs.writeFile(leaves.at(-1)!, 'changed final input');
        const changed = await nativeRawInputSnapshot({ projectRoot: root, previous: snapshot });
        expect(changed.complete, changed.diagnostics.join(';')).toBe(true);
        expect(changed.contentHash).not.toBe(snapshot.contentHash);
      }
    },
  );

  it('reads ignored generated bytes once and exposes raw paths inside a gitlink', async () => {
    await fs.writeFile(path.join(root, '.gitignore'), 'dist/\n');
    await fs.mkdir(path.join(root, 'dist'));
    await fs.writeFile(path.join(root, 'dist/generated.unknown'), 'generated bytes');
    const child = path.join(root, 'dependency');
    await fs.mkdir(child);
    git(child, 'init', '--quiet');
    git(child, 'config', 'user.name', 'Test');
    git(child, 'config', 'user.email', 'test@example.com');
    await fs.writeFile(path.join(child, 'module.unknown'), 'child bytes');
    git(child, 'add', '.');
    git(child, 'commit', '--quiet', '-m', 'child input');
    git(root, 'add', 'dependency');
    const probe = vi.spyOn(raceSafeRead, 'hashFileRaceSafe');
    const snapshot = await nativeRawInputSnapshot({ projectRoot: root });
    expect(snapshot.complete, snapshot.diagnostics.join(';')).toBe(true);
    expect(
      probe.mock.calls.filter(([file]) => file === path.join(root, 'dist/generated.unknown')),
    ).toHaveLength(1);
    expect(snapshot.files.some((file) => file.path === 'dependency/module.unknown')).toBe(true);
    expect(snapshot.repositories?.some((repository) => repository.path === 'dependency')).toBe(
      true,
    );
    const previousHash = snapshot.files.find(
      (file) => file.path === 'dependency/module.unknown',
    )!.hash;
    await fs.writeFile(path.join(child, 'module.unknown'), 'changed child bytes');
    const edited = await nativeRawInputSnapshot({ projectRoot: root, previous: snapshot });
    expect(edited.complete, edited.diagnostics.join(';')).toBe(true);
    expect(edited.files.find((file) => file.path === 'dependency/module.unknown')!.hash).not.toBe(
      previousHash,
    );
  });

  it.each(['new-generated-file', 'new-generated-directory', 'volatile-trace'])(
    'fences ignored input inventory without rejecting excluded output noise (%s)',
    async (change) => {
      await fs.writeFile(path.join(root, '.gitignore'), 'scratch/\n.next/\n');
      await fs.mkdir(path.join(root, 'scratch'), { recursive: true });
      await fs.writeFile(path.join(root, 'scratch', 'other.txt'), 'ignored discovery parent');
      await fs.mkdir(path.join(root, '.next', 'types'), { recursive: true });
      await fs.writeFile(path.join(root, '.next', 'types', 'input.unknown'), 'bound input');
      if (change === 'new-generated-file') {
        await fs.mkdir(path.join(root, 'scratch', 'app', 'dist'), { recursive: true });
        await fs.writeFile(path.join(root, 'scratch', 'app', 'dist', 'old.unknown'), 'original');
      }
      const before = await nativeRawInputSnapshot({ projectRoot: root });
      expect(before.complete, before.diagnostics.join(';')).toBe(true);
      const original = raceSafeRead.hashFileRaceSafe;
      let injected = false;
      vi.spyOn(raceSafeRead, 'hashFileRaceSafe').mockImplementation(async (...args) => {
        const result = await original(...args);
        if (!injected && args[0] === path.join(root, 'committed.txt')) {
          injected = true;
          if (change === 'volatile-trace')
            await fs.writeFile(path.join(root, '.next', 'trace'), 'excluded trace');
          else {
            await fs.mkdir(path.join(root, 'scratch', 'app', 'dist'), { recursive: true });
            await fs.writeFile(
              path.join(root, 'scratch', 'app', 'dist', 'added.unknown'),
              'new actual input',
            );
          }
        }
        return result;
      });
      const current = await nativeRawInputSnapshot({ projectRoot: root });
      expect(injected).toBe(true);
      expect(current.complete, current.diagnostics.join(';')).toBe(change === 'volatile-trace');
      if (change === 'volatile-trace') expect(current.contentHash).toBe(before.contentHash);
    },
  );

  it('rejects generated inputs added while repairing a cached leaf at the final capture fence', async () => {
    await fs.writeFile(path.join(root, '.gitignore'), 'scratch/\n');
    const generated = path.join(root, 'scratch', 'app', 'dist');
    await fs.mkdir(generated, { recursive: true });
    await fs.writeFile(path.join(generated, 'existing.unknown'), 'original generated input');
    const previous = await nativeRawInputSnapshot({ projectRoot: root });
    expect(previous.complete, previous.diagnostics.join(';')).toBe(true);
    const original = fs.lstat;
    let injected = false;
    vi.spyOn(fs, 'lstat').mockImplementation((async (...args: Parameters<typeof fs.lstat>) => {
      if (
        !injected &&
        String(args[0]) === path.join(root, 'committed.txt') &&
        (args[1] as { bigint?: boolean } | undefined)?.bigint
      ) {
        injected = true;
        await fs.writeFile(path.join(generated, 'late.unknown'), 'new generated input');
        await fs.writeFile(
          path.join(root, 'committed.txt'),
          'tracked input changed after the generated file',
        );
      }
      return original(...args);
    }) as typeof fs.lstat);
    const captured = await nativeRawInputSnapshot({ projectRoot: root, previous });
    expect(injected).toBe(true);
    expect(captured.complete).toBe(false);
    expect(captured.diagnostics.join(';')).toContain('scratch');
    vi.restoreAllMocks();
    const fresh = await nativeRawInputSnapshot({ projectRoot: root });
    expect(fresh.complete, fresh.diagnostics.join(';')).toBe(true);
    expect(fresh.files.some((file) => file.path === 'scratch/app/dist/late.unknown')).toBe(true);
    expect(fresh.contentHash).not.toBe(previous.contentHash);
  });

  it.each([true, false])(
    'keeps Archive generated-only snapshots equivalent without binding moved materials (git=%s)',
    async (useGit) => {
      if (!useGit) await fs.rm(path.join(root, '.git'), { recursive: true, force: true });
      await fs.writeFile(path.join(root, '.gitignore'), 'dist/\n.worktrees/\n');
      const active = 'docs/comet/changes/example';
      const archive = 'docs/comet/archive/example';
      for (const ref of [
        'dist/output.txt',
        '.worktrees/side/dist/noise.txt',
        `${active}/specs/build/spec.md`,
      ]) {
        await fs.mkdir(path.dirname(path.join(root, ref)), { recursive: true });
        await fs.writeFile(path.join(root, ref), 'original');
      }
      const input = {
        ...fingerprintInput(root),
        managedArtifactRoot: path.join(root, 'docs'),
        generatedInputExclusions: [active, archive],
      };
      const full = await nativeCheckInputSnapshot(input);
      const generated = await nativeGeneratedCheckInputSnapshot(input);
      expect(full.complete).toBe(true);
      expect(generated).toEqual({ complete: true, fingerprint: full.generatedInputFingerprint });
      await fs.mkdir(path.dirname(path.join(root, archive)), { recursive: true });
      await fs.rename(path.join(root, active), path.join(root, archive));
      expect(await nativeGeneratedCheckInputSnapshot(input)).toEqual(generated);
      await fs.writeFile(path.join(root, 'dist/output.txt'), 'changed');
      expect((await nativeGeneratedCheckInputSnapshot(input)).fingerprint).not.toBe(
        generated.fingerprint,
      );
    },
  );

  it.each([true, false])(
    'keeps nested linked worktrees outside the complete project input boundary (ignored=%s)',
    async (ignored) => {
      await fs.writeFile(
        path.join(root, '.gitignore'),
        `${ignored ? '.worktrees/\n' : ''}.next/\n`,
      );
      git(root, 'add', '.gitignore');
      git(root, 'commit', '--quiet', '-m', 'declare input boundaries');
      const input = fingerprintInput(root);
      const before = await nativeCheckInputSnapshot(input);
      const gate = await nativeCheckInputGate({ projectRoot: root, candidateId: null });
      const side = path.join(root, '.worktrees/side');
      git(root, 'worktree', 'add', '--quiet', '--detach', side);
      await fs.mkdir(path.join(side, 'dist'), { recursive: true });
      await fs.writeFile(path.join(side, 'dist/input.js'), 'other candidate');
      const after = await nativeCheckInputSnapshot(input);
      expect(after.complete, after.diagnostics.join('; ')).toBe(true);
      expect(after.contentFingerprint).toBe(before.contentFingerprint);
      expect(await nativeCheckInputGate({ projectRoot: root, candidateId: null })).toBe(gate);
      await fs.mkdir(path.join(root, '.next/dev/types'), { recursive: true });
      await fs.writeFile(
        path.join(root, '.next/dev/types/routes.d.ts'),
        'export type Route = "/";',
      );
      const generated = await nativeCheckInputSnapshot(input);
      expect(generated.complete).toBe(true);
      expect(generated.contentFingerprint).not.toBe(after.contentFingerprint);
      expect(await nativeCheckInputGate({ projectRoot: root, candidateId: null })).not.toBe(gate);
      const linked = await nativeCheckInputSnapshot(fingerprintInput(side));
      expect(linked.complete).toBe(true);
      expect(linked.contentFingerprint).not.toBe(generated.contentFingerprint);
    },
  );

  it('rejects a non-file repository entry inside declared generated input instead of silently skipping it', async () => {
    await fs.writeFile(path.join(root, '.gitignore'), 'dist/\n');
    git(root, 'add', '.gitignore');
    git(root, 'commit', '--quiet', '-m', 'declare generated inputs');
    git(root, 'worktree', 'add', '--quiet', '--detach', path.join(root, 'dist/nested'));
    const snapshot = await nativeCheckInputSnapshot(fingerprintInput(root));
    expect(snapshot.complete).toBe(false);
    expect(snapshot.diagnostics.join('; ')).toContain('不是普通文件：dist/nested/');
    expect(await nativeCheckInputGate({ projectRoot: root, candidateId: null })).toBeNull();
  });

  it('keeps a complete snapshot for a single-character dirty tracked path and binds untracked edits', async () => {
    await fs.writeFile(path.join(root, 'a'), 'base\n');
    git(root, 'add', 'a');
    git(root, 'commit', '--quiet', '-m', 'single-character path');
    await fs.writeFile(path.join(root, 'a'), 'dirty\n');
    await fs.writeFile(path.join(root, 'untracked'), 'first\n');
    const input = fingerprintInput(root);
    const before = await nativeCheckInputSnapshot(input);
    expect(before.complete, before.diagnostics.join('; ')).toBe(true);
    expect(await nativeCheckInputSnapshot(input)).toEqual(before);
    await fs.writeFile(path.join(root, 'untracked'), 'second\n');
    const after = await nativeCheckInputSnapshot(input);
    expect(after.complete, after.diagnostics.join('; ')).toBe(true);
    expect(after.contentFingerprint).not.toBe(before.contentFingerprint);
  });

  it('excludes declared Runtime-owned files inside generated roots without dropping production input', async () => {
    const managedArtifactRoot = path.join(root, 'dist');
    await fs.writeFile(path.join(root, '.gitignore'), 'dist/\n');
    const change = path.join(managedArtifactRoot, 'comet/changes/example');
    await fs.mkdir(change, { recursive: true });
    await fs.writeFile(path.join(change, 'comet-state.yaml'), 'state: one');
    await fs.writeFile(path.join(managedArtifactRoot, 'production.js'), 'one');
    const input = { ...fingerprintInput(root), managedArtifactRoot };
    const before = await nativeCheckInputSnapshot(input);
    await fs.writeFile(path.join(change, 'comet-state.yaml'), 'state: two');
    expect(await nativeCheckInputSnapshot(input)).toEqual(before);
    await fs.writeFile(path.join(managedArtifactRoot, 'production.js'), 'two');
    const after = await nativeCheckInputSnapshot(input);
    expect(after.complete).toBe(true);
    expect(after.contentFingerprint).not.toBe(before.contentFingerprint);
  });

  it('detects tracked submodules from the staged index stream', () => {
    expect(hasGitlinksInIndex('100644 abc\tREADME.md\0')).toBe(false);
    expect(hasGitlinksInIndex('160000 abc\tdependency\0')).toBe(true);
  });

  it('stays stable when an unbound environment variable changes', async () => {
    const before = await nativeCheckInputFingerprint(fingerprintInput(root));
    process.env.COMET_TEST_INCIDENTAL_VARIABLE = `session-${Date.now()}`;
    try {
      const after = await nativeCheckInputFingerprint(fingerprintInput(root));
      expect(after).toBe(before);
    } finally {
      delete process.env.COMET_TEST_INCIDENTAL_VARIABLE;
    }
  });

  it('changes when a tracked working-tree file changes and when a file is staged', async () => {
    const before = await nativeCheckInputFingerprint(fingerprintInput(root));

    await fs.writeFile(path.join(root, 'committed.txt'), 'committed and edited\n');
    const afterEdit = await nativeCheckInputFingerprint(fingerprintInput(root));
    expect(afterEdit).not.toBe(before);

    git(root, 'add', 'committed.txt');
    const afterStage = await nativeCheckInputFingerprint(fingerprintInput(root));
    expect(afterStage).not.toBe(afterEdit);
  });

  it('changes when a PATH entry is added because PATH stays bound', async () => {
    const before = await nativeCheckInputFingerprint(fingerprintInput(root));
    const previous = process.env.PATH;
    process.env.PATH = `${previous}${path.delimiter}${path.join(root, 'bin')}`;
    try {
      const after = await nativeCheckInputFingerprint(fingerprintInput(root));
      expect(after).not.toBe(before);
    } finally {
      process.env.PATH = previous;
    }
  });

  it('separates execution context from the complete candidate content snapshot', async () => {
    const before = await nativeCheckInputSnapshot(fingerprintInput(root));
    const prior = process.env.HTTP_PROXY;
    process.env.HTTP_PROXY = 'http://different-fixture-proxy.test:8080';
    try {
      const after = await nativeCheckInputSnapshot(fingerprintInput(root));
      expect(after.complete).toBe(true);
      expect(after.contentFingerprint).toBe(before.contentFingerprint);
