          repeatable: true,
        },
      ],
    };

    const before = await nativeCheckInputGate(gate);
    await fs.writeFile(path.join(root, 'dist', 'input.txt'), 'bad\n');
    expect(await nativeCheckInputGate(gate)).not.toBe(before);
