      expect(rejectedAction.rejectedOutcomes?.at(-1)?.outcome.output).toMatchObject({
        inputBefore: expect.any(String),
        inputAfter: expect.any(String),
        checks: [{ id: prepared.check.id, status: 'passed', exitCode: 0 }],
      });
