      JSON.parse(
        execFileSync(
          process.execPath,
          [path.join(repository, entry), 'joint-shape', ...args, '--project-root', root, '--json'],
          { cwd: root, encoding: 'utf8', timeout: 60_000 },
        ),
      );
    const prepared = execute('assets/skills/comet-native/scripts/comet-native-next.mjs', [
      '--summary',
