    parseCometHookRequest(
      JSON.stringify({ tool_name: 'Write', tool_input: { file_path: file, content } }),
    );
  return {
    base,
    root,
    paths,
    name,
    cli,
    inspect,
    state,
    runtime,
    claim,
    finishBuilder,
    request,
    briefFile,
    change,
  };
}

