describe('Classic upgraded preset archive recovery', () => {
  it.each([
    ['tweak', 'running'],
    ['tweak', 'unknown'],
    ['hotfix', 'running'],
    ['hotfix', 'unknown'],
  ] as const)('recovers %s after a moved %s Archive on cold start', async (profile, status) => {
    const f = await fixture(false, profile);
    const openSpec = await createOpenSpecArchiveFixture(path.dirname(f.projectRoot));
    await fs.appendFile(
      openSpec.command,
      "\nprocess.stderr.write('injected disconnect after move'); process.exit(1);\n",
    );
    vi.stubEnv('COMET_OPENSPEC', openSpec.command);
    await f.prepareBuild();
    await f.ok('state', 'submit-plan', 'example', '--plan', f.plan);
    await f.put(`${f.change}/tasks.md`, '- [x] Implement the adapter <!-- comet-task:impl -->\n');
    await f.ok(
      'guard',
      'example',
      'build',
      '--apply',
      '--',
      process.execPath,
      '-e',
      'process.exit(0)',
    );
    const report = 'docs/superpowers/reports/verify.md';
    await f.put(report, '# Verification\nAll current behavior checks pass.\n');
    await f.ok(
      'guard',
      'example',
      'verify',
      '--report',
      report,
      '--apply',
      '--',
      process.execPath,
      '-e',
      'process.exit(0)',
    );
    const proposal = await f.ok(
      'state',
      'propose-archive',
      'example',
      '--summary',
      'Archive locally.',
    );
    await f.ok(
      'state',
      'decide-archive',
      'example',
      '--proposal-hash',
      proposal.wait.proposalHash,
      '--choice',
      'local',
    );
    const { runtime, run } = await f.inspect();
    const preflighted = await executeClassicSdkArchivePreflight(runtime, {
      runId: run.runId,
      projectRoot: f.projectRoot,
    });
    if (status === 'unknown') {
      await expect(
        executeClassicSdkArchive(runtime, { runId: run.runId, projectRoot: f.projectRoot }),
      ).rejects.toThrow('injected disconnect');
    } else {
      const action = preflighted.actions.at(-1)!;
      expect(action.stepId).toBe('full.archive.execute');
      const claimed = await runtime.claim({
        runId: run.runId,
        actionId: action.id,
        attempt: action.attempt,
        inputHash: action.inputHash,
        executorId: 'comet-classic-archive',
        claimToken: randomUUID(),
      });
      const active = path.join(f.projectRoot, f.change);
      await recordClassicArchiveRequirements(f.projectRoot, active);
      // 模拟真实归档边界：先保存原执行输入，再发生外部目录搬迁。
      await prepareClassicArchiveInputs(
        f.projectRoot,
        claimed,
        claimed.actions.at(-1)!,
        'openspec/specs',
      );
      await fs.rename(active, path.join(path.dirname(active), 'archive', '2026-10-20-example'));
    }
    const cold = await f.inspect();
    expect(cold.profile).toBe('full');
    expect(cold.run.workflow.id).toBe(`comet-classic-${profile}`);
    expect(cold.state).toMatchObject({ workflow: 'full', phase: 'archive', archived: false });
    expect(cold.run.actions.at(-1)).toMatchObject({ stepId: 'full.archive.execute', status });
    expect((await f.ok('state', 'next', 'example')).nextAction).toMatchObject({
      kind: 'reconcile',
      stepId: 'full.archive.execute',
    });

    if (status === 'running') {
      // 原领取方可能仍在运行，目录搬迁不能代替停止或丢失执行上下文的证据。
      const blocked = await f.cli('archive', 'example', '--recover');
      expect(blocked.exitCode).not.toBe(0);
      expect(blocked.stderr).toContain('markUnknownRequest');
      expect((await f.ok('state', 'next', 'example')).continuation.commandArgs).toEqual([
        'comet',
        'state',
        'check',
        'example',
        'archive',
        '--recover',
        '--json',
      ]);
      expect((await f.inspect()).run.actions.at(-1)?.status).toBe('running');
      const diagnosis = await f.cli('state', 'check', 'example', 'archive', '--recover');
      const request = path.join(f.projectRoot, 'archive-reconciliation.json');
      expect(diagnosis.data.recovery.markUnknownRequest.operation).toBe('mark-unknown');
      await fs.writeFile(request, JSON.stringify(diagnosis.data.recovery.markUnknownRequest));
      const dispatch = await runtimeDispatchCommand(
        { request, application: `classic-${profile}`, projectRoot: f.projectRoot },
        { invocationCwd: f.projectRoot },
      );
      expect(dispatch.response.status).toBe('succeeded');
      expect((await f.inspect()).run.actions.at(-1)?.status).toBe('unknown');
    }

    if (profile === 'tweak' && status === 'unknown') {
      for (const corruption of ['claim', 'attempt', 'executor'] as const) {
        const forged = structuredClone(cold.run);
        const action = forged.actions.at(-1)!;
        if (corruption === 'claim') action.claim!.token = 'unrelated-claim';
        else if (corruption === 'attempt') action.attempt++;
        else action.claim!.executorId = 'unrelated-executor';
        const recordOutcome = vi.fn();
        await expect(
          recoverClassicSdkArchive(
            { inspect: async () => forged, recordOutcome },
            { projectRoot: f.projectRoot, runId: forged.runId },
          ),
        ).rejects.toThrow(/does not match|no single moved Action/u);
        expect(recordOutcome).not.toHaveBeenCalled();
      }
      const store = createClassicSdkStateStore(f.projectRoot);
      for (const corruption of ['choice', 'unresolved'] as const) {
        const current = (await f.inspect()).run;
        const forged = structuredClone(current);
        forged.revision++;
        const wait = forged.waits.find(
          (entry) => entry.stepId === 'tweak.build.escalation-confirm',
        )!;
        if (corruption === 'choice') wait.decision!.choice = 'continue';
        else {
          wait.status = 'cancelled';
          delete wait.decision;
        }
        expect(await store.compareAndSwap(current.runId, current.revision, forged)).toBe(true);
        await expect(f.inspect()).rejects.toThrow('does not match its change ownership');
        expect((await f.cli('archive', 'example', '--recover')).exitCode).not.toBe(0);
        expect(
          await store.compareAndSwap(current.runId, forged.revision, {
            ...current,
            revision: forged.revision + 1,
          }),
        ).toBe(true);
      }
    }

    if (profile === 'hotfix') {
      const originalRuntime = path.join(f.projectRoot, '.comet/runtime-before-moved-restore');
      await fs.rename(resolveWorkspaceRuntimeRootSync(f.projectRoot), originalRuntime);
      await f.ok('state', 'next', 'example');
      expect((await f.inspect()).run.actions.at(-1)?.status).toBe('unknown');
      // 便携检查点不能补造外部执行前的文件快照，必须带回原设备保存的收据。
      const missing = await f.cli('archive', 'example', '--recover');
      expect(missing.exitCode).not.toBe(0);
      expect(missing.stderr).toContain('缺少原始执行清单');
      await fs.cp(
        path.join(originalRuntime, 'archive-inputs'),
        path.join(resolveWorkspaceRuntimeRootSync(f.projectRoot), 'archive-inputs'),
        { recursive: true },
      );
    }
    expect((await f.ok('state', 'next', 'example')).continuation.commandArgs).toEqual([
      'comet',
      'archive',
      'example',
      '--recover',
      '--json',
    ]);
    const recovery = await f.ok('archive', 'example', '--recover');
    expect(recovery.recoveredAction).toBe(cold.run.actions.at(-1)!.id);
    const recovered = await f.inspect();
    expect(recovered.state.archived).toBe(true);
    expect(recovered.run.actions.at(-1)).toMatchObject({
      stepId: 'full.archive.deliver',
      status: 'pending',
    });
    if (status === 'unknown') expect(await openSpec.invocations()).toHaveLength(1);
    await fs.rename(
      resolveWorkspaceRuntimeRootSync(f.projectRoot),
      path.join(f.projectRoot, '.comet/runtime-before-archive-restore'),
    );
    await f.ok('state', 'next', 'example');
    const restored = await f.inspect();
    expect(restored.profile).toBe('full');
    expect(restored.state.archived).toBe(true);
    expect(restored.run.actions.at(-1)).toMatchObject({
      stepId: 'full.archive.deliver',
      status: 'pending',
    });
  });
});

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';

describe.each(['skills-zh', 'skills'])('%s SDK flow handoffs', (root) => {
  const read = (ref: string) => fs.readFile(path.resolve('assets', root, ref), 'utf8');
  it('routes preset scope checks to the matching Runtime reference without repeating file-count authorization', async () => {
    const entry = await read('comet-classic/SKILL.md');
    const section = root === 'skills-zh' ? '预设范围复核' : 'Preset scope';
    expect(entry).toContain(
      `reference/sdk-methods.md#${section.toLowerCase().replaceAll(' ', '-')}`,
    );
    expect(await read('comet-classic/reference/sdk-methods.md')).toContain(`## ${section}`);
    expect(entry).toContain('rulings.md');
    expect(entry).toContain('reference/compat.md');
    expect(entry).not.toContain('文件数超过提示阈值时，展示');
    expect(entry).not.toContain('changed-file count exceeds the advisory threshold, present');
  });
  it('discloses Compat commands separately and retains SDK methods and approvals', async () => {
    for (const name of [
      'comet-design',
      'comet-build',
      'comet-verify',
      'comet-archive',
      'comet-hotfix',
      'comet-tweak',
    ]) {
      const main = await read(`${name}/SKILL.md`);
      expect(main).toContain('](reference/compat.md)');
      expect(main).toContain('../comet-classic/reference/sdk-methods.md');
      expect(main).not.toContain('comet state set <name>');
      const compat = await read(`${name}/reference/compat.md`);
      expect(compat).toContain('comet state select');
    }
    const methods = await read('comet-classic/reference/sdk-methods.md');
    for (const contract of [
      'configuration.language',
      'comet-task-authority',
      'base-ref',
      'CRITICAL/IMPORTANT',
      '--local',
      'rulings.md',
      'complete-delivery',
    ])
      expect(methods).toContain(contract);
    for (const name of ['comet-hotfix', 'comet-tweak']) {
      const main = await read(`${name}/SKILL.md`);
      expect(main).toContain('open --json');
      expect(main).toContain('open --apply --approval-hash');
    }
  });
  it('submits checked Design, Verify, and Archive directly and supports explicit configuration approval', async () => {
    expect(await read('comet-design/SKILL.md')).not.toContain(
      '`comet guard <change-name> design --design-doc <design-doc-ref>`',
    );
    expect(await read('comet-verify/SKILL.md')).not.toContain(
      '`comet guard <change-name> verify --report <report-ref>`',
    );
    expect(await read('comet-archive/SKILL.md')).not.toContain(
      '`comet guard <change-name> archive`',
    );
    expect(await read('comet-build/SKILL.md')).toContain(
      'propose-build <change-name> --file <configuration-json> --confirmed',
    );
  });
  it('ships the complete edit-review protocol and distinguishes SDK Archive from Git delivery', async () => {
    const review = await read('comet/reference/edit-review.md');
    for (const command of [
      'claim',
      'recordTemplate',
      'non-behavioral',
      'implementation-changed',
      'requirements-changed',
      'discard',
      '--confirmed',
    ])
      expect(review).toContain(command);
    const native = await read('comet-native/SKILL.md');
    expect(native).toContain('reference/edit-review.md');
    expect(await read('comet-native/reference/edit-review.md')).toBe(review);
    expect(native).toContain('SDK');
    expect(native).toContain('Compat');
    const workspace = await read('comet-native/reference/workspace.md');
    expect(workspace).toContain('SDK');
    expect(workspace).toContain('SHA');
    expect(workspace).toContain('Compat');
  });
  it('distinguishes refreshed check evidence from product implementation changes', async () => {
    const review = await read('comet/reference/edit-review.md');
    const boundaries =
      root === 'skills-zh'
        ? [
            '产品行为与验收含义不变',
            '检查证据需要更新',
            '产品实现变化',
            '说明文字参与实际产品行为时',
            '保留原报告、批准和候选',
          ]
        : [
            'product behavior and acceptance meaning stay unchanged',
            'check evidence needs updating',
            'product implementation change',
            'explanatory text participates in actual product behavior',
            'keep the original report, approvals, and candidate',
          ];
    for (const boundary of boundaries) expect(review).toContain(boundary);
    for (const decision of ['non-behavioral', 'implementation-changed', 'requirements-changed'])
      expect(review).toContain(decision);
    expect(review).toContain('refreshInputTemplate');
    expect(review).toContain('retainedChecks');
    expect(await read('comet-native/reference/edit-review.md')).toBe(review);
  });
  it('routes actual edits through review before phase or revision commands', async () => {
    const classic = await read('comet-classic/SKILL.md');
    const native = await read('comet-native/SKILL.md');
    expect(classic).toContain('../comet/reference/edit-review.md');
    expect(native).toContain('reference/edit-review.md');
    for (const entry of [classic, native]) {
      expect(entry).toContain(root === 'skills-zh' ? '实际文件变化' : 'actual file changes');
      expect(entry).toContain(
        root === 'skills-zh'
          ? '修订命令不构成用户授权'
          : 'revision commands do not grant user authorization',
      );
    }
  });

  it('retains checks for every formal edit and supplements only the original Agent judgment', async () => {
    const review = await read('comet/reference/edit-review.md');
    const boundaries =
      root === 'skills-zh'
        ? ['每份正式材料', '全部实际差异', '同一提案', '原 Agent', '追加保留检查', '未选检查']
        : [
            'each formal material',
            'all actual changes',
            'same proposal',
            'original Agent',
            'add retained checks',
            'unselected check',
          ];
    for (const boundary of boundaries) expect(review).toContain(boundary);
    expect(await read('comet-native/reference/edit-review.md')).toBe(review);
  });

  it('keeps an unapproved requirement revision from changing the original phase or results', async () => {
    const review = await read('comet/reference/edit-review.md');
    const boundaries =
      root === 'skills-zh'
        ? ['不构成用户授权', '保留原阶段、已接受结果和待办', '未覆盖的目标']
        : [
            'does not grant user authorization',
            'preserve the original phase, accepted results, and pending work',
            'targets not yet covered',
          ];
    for (const boundary of boundaries) expect(review).toContain(boundary);
    expect(review).toContain('prepare-applied');
    expect(review).toContain('--file');
    expect(review).toContain('requirements-changed');
    expect(await read('comet-native/reference/edit-review.md')).toBe(review);
  });
});

import { resolveClassicRunDirectory } from '../../../domains/comet-classic/classic-runtime-paths.js';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import {
  computeContextHash,
  validateClassicSdkDesignContext,
  writeClassicSdkDesignContext,
} from '../../../domains/comet-classic/classic-handoff.js';
import { runClassicCli } from '../../../domains/comet-classic/classic-cli.js';
import { readRunState } from '../../../domains/engine/state.js';
import { readClassicState } from '../../../domains/comet-classic/classic-store.js';
import { prepareClassicLegacyProject } from '../../helpers/classic-project.js';
import { withClassicSourceObservation } from '../../../domains/comet-classic/classic-protected-path.js';
import { classicOpenEvidenceReceipt } from '../../../domains/comet-classic/classic-sdk-application.js';

describe('Classic handoff material reuse', () => {
  let root: string;
  let changeDir: string;
  let sources: string[];
  beforeEach(async () => {
    root = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-handoff-budget-'));
    await prepareClassicLegacyProject(root);
    changeDir = path.join(root, 'openspec', 'changes', 'demo');
    await fs.mkdir(changeDir, { recursive: true });
    sources = ['proposal.md', 'design.md', 'tasks.md'].map((name) => path.join(changeDir, name));
    for (let index = 0; index < 10; index += 1) {
      const spec = path.join(changeDir, 'specs', `capability-${index}`, 'spec.md');
      await fs.mkdir(path.dirname(spec), { recursive: true });
      sources.push(spec);
    }
    await Promise.all(
      sources.map((file) => fs.writeFile(file, `# ${path.basename(file)}\n\n- [ ] implement\n`)),
    );
  });
  afterEach(async () => {
    vi.restoreAllMocks();
    await fs.rm(root, { recursive: true, force: true });
  });

  async function initializeDesignContext() {
    const initialized = await runClassicCli(
      ['state', 'init', 'demo', 'full', '--runtime', 'compat'],
      undefined,
      { projectRoot: root, invocationCwd: root },
    );
    expect(initialized.exitCode, initialized.stderr).toBe(0);
  }

  it.each(['off', 'beta'] as const)(
    'reads each source once per %s preparation and once per commit validation',
    async (contextCompression) => {
      await initializeDesignContext();
      const open = vi.spyOn(fs, 'open');
      const options = { projectRoot: root, changeDir, change: 'demo', contextCompression };
      const prepared = await writeClassicSdkDesignContext(options);
      for (const file of sources)
        expect(open.mock.calls.filter(([target]) => String(target) === file)).toHaveLength(1);
      open.mockClear();
      expect(await validateClassicSdkDesignContext({ ...options, ...prepared })).toBe(true);
      for (const file of sources)
        expect(open.mock.calls.filter(([target]) => String(target) === file)).toHaveLength(1);
      expect(prepared.handoffHash).toBe(
        await computeContextHash(root, changeDir, 'openspec/changes/demo'),
      );
      const document = JSON.parse(
        await fs.readFile(path.join(root, prepared.handoffContext), 'utf8'),
      );
      expect(document.files).toHaveLength(sources.length);
      if (contextCompression === 'beta') {
        const markdown = await fs.readFile(
          path.join(root, prepared.handoffContext.replace(/\.json$/u, '.md')),
          'utf8',
        );
        for (let index = 0; index < 10; index += 1) {
          expect(markdown).toContain(`## openspec/changes/demo/specs/capability-${index}/spec.md`);
        }
        expect(markdown).toContain('```md\n# spec.md');
        expect(markdown).not.toContain('No delta spec files found.');
      }
    },
  );

  it('shares one source observation across proposal evidence, requirements and handoff rendering', async () => {
    await initializeDesignContext();
    const open = vi.spyOn(fs, 'open');
    await withClassicSourceObservation(root, async () => {
      await classicOpenEvidenceReceipt(root, 'openspec/changes/demo');
      await classicOpenEvidenceReceipt(root, 'openspec/changes/demo', { designRequirements: true });
      await writeClassicSdkDesignContext({
        projectRoot: root,
        changeDir,
        change: 'demo',
        contextCompression: 'off',
      });
    });
    for (const file of sources)
      expect(
        open.mock.calls.filter(([target]) => String(target) === file),
        file,
      ).toHaveLength(1);
  });

  it.each(['edit', 'add', 'remove'] as const)(
    'rechecks source %s after preparing a handoff',
    async (change) => {
      await initializeDesignContext();
      const options = {
        projectRoot: root,
        changeDir,
        change: 'demo',
        contextCompression: 'off' as const,
      };
      const prepared = await writeClassicSdkDesignContext(options);
      if (change === 'edit') await fs.appendFile(sources[0], '\nchanged\n');
      else if (change === 'remove') await fs.unlink(sources.at(-1)!);
      else {
        const spec = path.join(changeDir, 'specs', 'new', 'spec.md');
        await fs.mkdir(path.dirname(spec));
        await fs.writeFile(spec, '# New requirement\n');
      }
      expect(await validateClassicSdkDesignContext({ ...options, ...prepared })).toBe(false);
    },
  );

  it('rejects a replaced source symlink at validation', async (context) => {
    await initializeDesignContext();
    const options = {
      projectRoot: root,
      changeDir,
      change: 'demo',
      contextCompression: 'off' as const,
    };
    const prepared = await writeClassicSdkDesignContext(options);
    await fs.unlink(sources[0]);
    try {
      await fs.symlink(sources[1], sources[0]);
    } catch (error) {
      if (process.platform === 'win32' && (error as NodeJS.ErrnoException).code === 'EPERM') {
        context.skip('当前 Windows 环境未允许创建文件符号链接');
      }
      throw error;
    }
    await expect(validateClassicSdkDesignContext({ ...options, ...prepared })).rejects.toThrow(
      /symbolic link|junction/i,
    );
  });

  it('releases only its stale handoff claim so a changed source can be retried', async () => {
    const run = (args: string[]) =>
      runClassicCli(args, undefined, { projectRoot: root, invocationCwd: root });
    expect((await run(['state', 'init', 'demo', 'full', '--runtime', 'compat'])).exitCode).toBe(0);
    expect((await run(['state', 'transition', 'demo', 'open-complete'])).exitCode).toBe(0);
    const rename = fs.rename.bind(fs);
    let changed = false;
    vi.spyOn(fs, 'rename').mockImplementation(async (...args: Parameters<typeof fs.rename>) => {
      const result = await rename(...args);
      if (
        !changed &&
        String(args[1]).endsWith(`${path.sep}handoff${path.sep}design-context.json`)
      ) {
        changed = true;
        await fs.appendFile(sources[0], '\nsource changed during preparation\n');
      }
      return result;
    });
    const rejected = await run(['handoff', 'demo', 'design', '--write']);
    expect(changed).toBe(true);
    expect(rejected.exitCode).not.toBe(0);
    expect(rejected.stderr).toContain('handoff sources changed before completion');
    expect((await readClassicState(changeDir)).classic?.handoffHash).toBeNull();
    expect((await readRunState(await resolveClassicRunDirectory(changeDir)))?.pending).toBeNull();
    const retried = await run(['handoff', 'demo', 'design', '--write']);
    expect(retried.exitCode, retried.stderr).toBe(0);
    expect((await readRunState(await resolveClassicRunDirectory(changeDir)))?.pending).toBeNull();
    expect((await readClassicState(changeDir)).classic?.handoffHash).toBe(
      await computeContextHash(root, changeDir, 'openspec/changes/demo'),
    );
  });
});

import { execFileSync } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, expect, it, vi } from 'vitest';
import { runClassicCli } from '../../../domains/comet-classic/classic-cli.js';
import { inspectClassicSdkRun } from '../../../domains/comet-classic/classic-sdk-status.js';
import { runClassicEditReviewCommand } from '../../../domains/comet-classic/classic-edit-review-command.js';
import { inspectClassicHookGuard } from '../../../domains/comet-classic/classic-hook-guard.js';
import { parseCometHookRequest } from '../../../platform/process/hook-adapter.js';
import { prepareClassicLegacyProject } from '../../helpers/classic-project.js';

const roots: string[] = [];
afterEach(async () => {
  vi.unstubAllEnvs();
  await Promise.all(roots.splice(0).map((root) => fs.rm(root, { recursive: true, force: true })));
});

it('reviews a generic edit after a normal SDK Build and continues Verify without a stuck claimed Action', async () => {
  const base = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-sdk-edit-review-'));
  roots.push(base);
  const root = path.join(base, 'project');
  const home = path.join(base, 'home');
  await fs.mkdir(home);
  vi.stubEnv('HOME', home);
  vi.stubEnv('USERPROFILE', home);
  vi.stubEnv('XDG_DATA_HOME', path.join(home, '.local/share'));
  await prepareClassicLegacyProject(root);
  const git = (...args: string[]) => execFileSync('git', args, { cwd: root, stdio: 'ignore' });
  git('init', '-b', 'main');
  git(
    '-c',
    'user.name=Test',
    '-c',
    'user.email=test@example.invalid',
    'commit',
    '--allow-empty',
    '-m',
    'baseline',
  );
  const cli = async (...args: string[]) => {
    const separator = args.indexOf('--');
    args.splice(separator < 0 ? args.length : separator, 0, '--json');
    const result = await runClassicCli(args, undefined, { projectRoot: root, invocationCwd: root });
    expect(result.exitCode, result.stdout).toBe(0);
    return JSON.parse(result.stdout!);
  };
  await cli('state', 'init', 'demo', 'tweak', '--isolation', 'current');
  const change = path.join(root, 'openspec/changes/demo');
  for (const [ref, source] of Object.entries({
    'proposal.md': '# Proposal\nPreserve the worker behavior.\n',
    'design.md': '# Design\nPreserve behavior.\n',
    'tasks.md': '- [x] Implement the worker\n',
  }))
    await fs.writeFile(path.join(change, ref), source);
  await fs.writeFile(path.join(root, 'worker.py'), 'value = 1\n');
  const preview = await cli('guard', 'demo', 'open');
  await cli('guard', 'demo', 'open', '--apply', '--approval-hash', preview.data.approvalHash);
  await cli(
    'guard',
    'demo',
    'build',
    '--apply',
    '--session',
    'builder-session',
    '--',
    process.execPath,
    '-e',
    '',
  );
  const run = (await inspectClassicSdkRun(root, 'demo')).run;
  expect(
    run.actions.find((action) => action.stepId === 'tweak.build.execute')?.claim?.sessionId,
  ).toBe('builder-session');
  const after = '# Explanation.\nvalue = 1\n';
  const input = {
    tool_name: 'Write',
    tool_input: { file_path: path.join(root, 'worker.py'), content: after },
  };
  const request = parseCometHookRequest(JSON.stringify(input));
  expect((await inspectClassicHookGuard(root, 'demo', request)).allowed).toBe(true);
  await fs.writeFile(path.join(root, 'worker.py'), after);
  const claimed = await runClassicEditReviewCommand({
    projectRoot: root,
    name: 'demo',
    operation: 'observe',
    sessionId: 'builder-session',
  });
  const template = claimed as {
    recordTemplate: Record<string, unknown>;
    observation: { changes: Array<{ path: string }> };
  };
  expect(template.observation.changes.some((entry) => entry.path === 'worker.py')).toBe(true);
  const recordFile = path.join(base, 'review.json');
  await fs.writeFile(
    recordFile,
    JSON.stringify({
      ...template.recordTemplate,
      decision: 'non-behavioral',
      summary: 'The explanation changes no behavior or acceptance conditions.',
    }),
  );
  await runClassicEditReviewCommand({
    projectRoot: root,
    name: 'demo',
    operation: 'record',
    file: recordFile,
  });
  expect((await inspectClassicHookGuard(root, 'demo', request)).allowed).toBe(true);
  expect(await fs.readFile(path.join(root, 'worker.py'), 'utf8')).toBe(after);
  const current = (await inspectClassicSdkRun(root, 'demo')).run;
  expect(current.actions).toEqual(run.actions);
  const report = 'docs/superpowers/reports/verify.md';
  await fs.mkdir(path.dirname(path.join(root, report)), { recursive: true });
  await fs.writeFile(
    path.join(root, report),
    '# Verification\nThe worker behavior is unchanged.\n',
  );
  expect(
    (
      await cli(
        'guard',
        'demo',
        'verify',
        '--report',
        report,
        '--apply',
        '--',
        process.execPath,
        '-e',
        '',
      )
    ).data.phase,
  ).toBe('archive');
  const formalFile = path.join(change, 'proposal.md');
  const originalFormal = await fs.readFile(formalFile, 'utf8');
  await fs.appendFile(formalFile, '\n<!-- clarify the same scope -->\n');
  const observedFormal = await runClassicEditReviewCommand({
    projectRoot: root,
    name: 'demo',
    operation: 'observe',
    sessionId: 'builder-session',
  });
  expect(observedFormal).toHaveProperty('formalReview');
  expect(observedFormal.formalReview).toMatchObject({
    originals: [{ path: 'openspec/changes/demo/proposal.md', text: originalFormal }],
  });
  expect(JSON.stringify(observedFormal.formalReview)).toContain('proposal.md');
  expect(JSON.stringify(observedFormal.formalReview)).toContain(
    originalFormal.trim().split('\n').at(-1)!,
  );
  expect(JSON.stringify(observedFormal.formalReview)).toContain('recordTemplate');
});

import { readSkillWithCompat } from '../../helpers/skill-content.js';
