describe('Classic decision guidance routing', () => {
  it.each([
    {
      language: 'Chinese',
      root: zhSkillRoot,
      sdkHeading: '## SDK Run 路径',
      compatHeading: '## Compat 路径',
      configuration: ['执行配置展示', '执行配置展示'],
