            expect(
              args
                .slice(2)
                .reduce(
                  (total, ref) => total + Buffer.byteLength(JSON.stringify(ref), 'utf8') + 1,
                  0,
                ),
            ).toBeLessThanOrEqual(8_192);
          }
        } finally {
          longCalls.mockRestore();
        }
      }
      const altered = path.join(archived.archiveDir, files[0]);
