        exitCode: 0,
        data: {
          state: {
            phase: 'verify',
            status: 'active',
            verification_result: 'pending',
            loop: { stage: 'verify-ready', next_action: 'run-final-full-verification' },
          },
        },
      });
      await expect(fs.stat(transactionFile)).rejects.toMatchObject({ code: 'ENOENT' });
    } finally {
