  return {
    status: 'passed' as const,
    summary: 'Independent read-only review passed.',
    reviewerExecutionRef,
  };
}

describe('Native phase Hook guard', () => {
  let projectRoot: string;

  async function useRevertPolicy(artifactRoot = 'docs'): Promise<void> {
    const config = defaultProjectConfig(artifactRoot, 'en');
    await writeProjectConfig(projectRoot, {
      ...config,
      native: { ...config.native, document_writes: 'revert' },
    });
  }

  const writeRequest = (...targets: string[]): NativeHookRequest => ({
    intent: targets.length > 0 ? 'write' : 'unknown',
    targets,
  });

  const nonWriteRequest = (): NativeHookRequest => ({ intent: 'non-write', targets: [] });

  async function addHookAllowPath(relativePath: string): Promise<void> {
    await fs.appendFile(
      path.join(projectRoot, '.comet', 'config.yaml'),
      `hook:\n  allow_paths:\n    - ${relativePath}\n`,
    );
  }

  async function activeChange(
    phase: 'shape' | 'build' | 'verify' | 'archive',
    name: string,
    artifactRoot = '.',
  ) {
    const paths = await nativeProjectPaths(projectRoot, artifactRoot);
    await ensureNativeDirectories(paths);
    const state = await createNativeChange({
      paths,
      name,
      language: 'en',
      verificationProtocol: 'legacy-v1',
    });
    state.phase = phase;
    await writeNativeChange(paths, state);
    return { paths, state };
  }

  async function portableBuild(name: string, artifactRoot = '.') {
    const paths = await nativeProjectPaths(projectRoot, artifactRoot);
    await ensureNativeDirectories(paths);
    await createNativePortableChange({ paths, name, language: 'en' });
    await fs.writeFile(
      path.join(nativePortableChangeDir(paths, name), 'brief.md'),
      '# Acceptance examples\n- The implementation exposes the requested behavior.\n',
    );
    const state = await confirmNativePortableShape({ paths, name });
    return { paths, state };
  }

  beforeEach(async () => {
    projectRoot = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-hook-'));
    execFileSync('git', ['init'], { cwd: projectRoot, stdio: 'ignore' });
  });

  afterEach(async () => {
    vi.restoreAllMocks();
    await fs.rm(projectRoot, { recursive: true, force: true });
  });

  it('shares the selected state read within a Hook decision and refreshes the next decision', async () => {
    await writeProjectConfig(projectRoot, defaultProjectConfig());
    const { paths, state } = await activeChange('shape', 'selected-read', 'docs');
    const stateFile = path.join(paths.changesDir, state.name, 'comet-state.yaml');
    const read = vi.spyOn(fs, 'readFile');
    const open = vi.spyOn(fs, 'open');
    await runWithHookReadCache(async () => {
      expect(await resolveActiveNativeHookChange(projectRoot, state.name)).toMatchObject({
        phase: 'shape',
      });
      expect(
        await inspectNativeHookGuard(projectRoot, writeRequest('docs/readme.md'), state.name),
      ).toMatchObject({ allowed: true, phase: 'shape' });
    });
    // The legacy schema probe and state parse each read once, instead of being repeated by the Guard.
    expect(
      read.mock.calls.filter(([file]) => String(file) === stateFile).length +
        open.mock.calls.filter(([file]) => String(file) === stateFile).length,
    ).toBe(2);
    await writeNativeChange(paths, { ...state, phase: 'build' });
    await runWithHookReadCache(async () => {
      expect(
        await inspectNativeHookGuard(projectRoot, writeRequest('src/index.ts'), state.name),
      ).toMatchObject({ allowed: true, phase: 'build' });
    });
  });

  it('discards the selected Hook snapshot before returning a candidate to Build', async () => {
    await useRevertPolicy();
    await writeProjectConfig(projectRoot, defaultProjectConfig());
    const { paths, state } = await portableBuild('hook-invalidates', 'docs');
    await fs.writeFile(path.join(projectRoot, 'AGENTS.md'), 'Run checks.\n');
    await submitNativePortableBuilderCandidate({
      paths,
      name: state.name,
      input: {
        identity: createNativeRunnerChannel().captureExecutionIdentity({
          identityProvider: 'test-host',
          executionRef: 'hook-builder',
        }),
        candidateId: 'hook-candidate',
        summary: 'Implemented the requested behavior.',
        addressedAcceptanceIds: ['A1'],
        acceptanceReview: fixtureAcceptanceReview(['A1']),
      },
    });
    const returnToBuild = portableRuntime.returnNativePortableChangeToBuild;
    vi.spyOn(portableRuntime, 'returnNativePortableChangeToBuild').mockImplementationOnce(
      async (options) => {
        // A nested observer may populate another snapshot while the mutation is pending.
        expect(await resolveActiveNativeHookChange(projectRoot, state.name)).toMatchObject({
          phase: 'verify',
        });
        return returnToBuild(options);
      },
    );
    await runWithHookReadCache(async () => {
      expect(await resolveActiveNativeHookChange(projectRoot, state.name)).toMatchObject({
        phase: 'verify',
      });
      expect(
        await inspectNativeHookGuard(
          projectRoot,
          {
            intent: 'write',
            targets: ['AGENTS.md'],
            toolName: 'Write',
            writes: [{ path: 'AGENTS.md', content: 'Skip checks.\n' }],
          },
          state.name,
        ),
      ).toMatchObject({ allowed: true, phase: 'build' });
      expect(await resolveActiveNativeHookChange(projectRoot, state.name)).toMatchObject({
        phase: 'build',
      });
    });
  });

  it('normalizes Claude-compatible and native Hook payloads with every write target', () => {
    expect(
      parseNativeHookRequest(
        JSON.stringify({
          tool_name: 'Edit',
          tool_input: { file_path: 'src/index.ts', paths: ['src/a.ts', 'src/b.ts'] },
        }),
      ),
    ).toEqual({ intent: 'write', targets: ['src/index.ts', 'src/a.ts', 'src/b.ts'] });

    expect(
      parseNativeHookRequest(
        JSON.stringify({
          toolName: 'edit',
          toolArgs: JSON.stringify({ filePath: 'src/copilot.ts' }),
        }),
      ),
    ).toEqual({ intent: 'write', targets: ['src/copilot.ts'] });
  });

  it('extracts every target from apply_patch headers', () => {
    expect(
      parseNativeHookRequest(
        JSON.stringify({
          toolName: 'apply_patch',
          toolArgs: {
            patch: [
              '*** Begin Patch',
              '*** Update File: src/existing.ts',
              '*** Add File: src/new.ts',
              '*** Delete File: src/old.ts',
              '*** End Patch',
            ].join('\n'),
          },
        }),
      ),
    ).toEqual({
      intent: 'write',
      targets: ['src/existing.ts', 'src/new.ts', 'src/old.ts'],
    });
  });

  it('distinguishes explicit non-write tools from unknown write payloads', () => {
    expect(parseNativeHookRequest(JSON.stringify({ toolName: 'view', toolArgs: {} }))).toEqual({
      intent: 'non-write',
      targets: [],
    });
    expect(parseNativeHookRequest(JSON.stringify({ tool_name: 'Write', tool_input: {} }))).toEqual({
      intent: 'unknown',
      targets: [],
    });
    expect(parseNativeHookRequest('{broken')).toEqual({ intent: 'unknown', targets: [] });
    expect(parseNativeHookRequest('')).toEqual({ intent: 'unknown', targets: [] });
  });

  it.each([
    ['shape', false],
    ['build', true],
    ['verify', false],
    ['archive', false],
  ] as const)('%s applies the ordinary project write boundary', async (phase, allowed) => {
    await writeProjectConfig(projectRoot, defaultProjectConfig('.'));
    await activeChange(phase, `guard-${phase}`);

    await expect(
      inspectNativeHookGuard(projectRoot, writeRequest('src/index.ts')),
    ).resolves.toMatchObject({
      allowed,
      phase,
      change: `guard-${phase}`,
    });
  });

  it('guards an SDK-owned Shape from its Run while retaining the portable state file', async () => {
    await useRevertPolicy();
    const created = await runNativeCli([
      'new',
      'sdk-guard',
      '--runtime',
      'sdk',
      '--project-root',
      projectRoot,
      '--json',
    ]);
    expect(created.exitCode, created.stderr).toBe(0);

    await expect(listActiveNativeHookChanges(projectRoot)).resolves.toContainEqual({
      workflow: 'native',
      name: 'sdk-guard',
      phase: 'shape',
    });
    await expect(resolveActiveNativeHookChange(projectRoot, 'sdk-guard')).resolves.toMatchObject({
      workflow: 'native',
      name: 'sdk-guard',
      phase: 'shape',
    });
    await expect(
      inspectNativeHookGuard(projectRoot, writeRequest('src/index.ts'), 'sdk-guard'),
    ).resolves.toMatchObject({ allowed: false, change: 'sdk-guard', phase: 'shape' });
    await expect(
      inspectNativeHookGuard(
        projectRoot,
        writeRequest('docs/comet/changes/sdk-guard/brief.md'),
        'sdk-guard',
      ),
    ).resolves.toMatchObject({ allowed: true, change: 'sdk-guard', phase: 'shape' });

    const paths = await nativeProjectPaths(projectRoot, 'docs');
    const changeDir = path.join(paths.changesDir, 'sdk-guard');
    await fs.writeFile(
      path.join(changeDir, 'brief.md'),
      '# Outcome\nShip the workflow.\n# Scope\nKeep compatibility.\n## Directory structure\n### Modified\n- src/: preserve the workflow.\n# Non-goals\nNone.\n# Acceptance examples\n- The workflow resumes.\n# Constraints and invariants\nPreserve state.\n# Decisions\nNone.\n# Open questions\nNone.\n# Verification expectations\nRun focused checks.\n',
    );
    await fs.mkdir(path.join(changeDir, 'specs', 'workflow'), { recursive: true });
    await fs.writeFile(
      path.join(changeDir, 'specs', 'workflow', 'spec.md'),
      '# Workflow\nThe workflow resumes without losing confirmed work.\n',
    );
    const prepared = await runNativeCli([
      'next',
      'sdk-guard',
      '--project-root',
      projectRoot,
      '--json',
    ]);
    expect(prepared.exitCode, prepared.stderr ?? prepared.stdout).toBe(0);
    const stateVersion = (JSON.parse(prepared.stdout!) as { data: { stateVersion: number } }).data
      .stateVersion;
    const confirmed = await runNativeCli([
      'next',
      'sdk-guard',
      '--confirmed',
      '--summary',
      'User approved Shape.',
      '--expected-state-version',
      String(stateVersion),
      '--expected-action',
      'confirm-shape',
      '--project-root',
      projectRoot,
      '--json',
    ]);
    expect(confirmed.exitCode, confirmed.stderr).toBe(0);
    await expect(
      inspectNativeHookGuard(projectRoot, writeRequest('src/index.ts'), 'sdk-guard'),
    ).resolves.toMatchObject({ allowed: true, change: 'sdk-guard', phase: 'build' });
    await expect(
      inspectNativeHookGuard(
        projectRoot,
        writeRequest('docs/comet/changes/sdk-guard/brief.md'),
        'sdk-guard',
      ),
    ).resolves.toMatchObject({ allowed: true, change: 'sdk-guard', phase: 'build' });
    const { run } = await inspectNativeSdkRun(projectRoot, 'sdk-guard');
    const builder = run.actions.at(-1)!;
    const runtime = createNativeSdkRuntime(projectRoot);
    const context = { requestId: 'sdk-hook-builder', projectRoot };
    const claimed = await runtime.claim({
      runId: run.runId,
      actionId: builder.id,
      attempt: builder.attempt,
      inputHash: builder.inputHash,
      executorId: 'native-host',
      sessionId: 'sdk-hook-builder-session',
      claimToken: 'sdk-hook-builder-claim',
      context,
    });
    await runtime.recordOutcome({
      runId: run.runId,
      outcome: {
        actionId: builder.id,
        attempt: builder.attempt,
        inputHash: builder.inputHash,
        claimToken: claimed.actions.find((action) => action.id === builder.id)!.claim!.token,
        outcomeId: 'sdk-hook-builder-result',
        status: 'succeeded',
        output: {
          summary: 'Implemented the workflow.',
          addressedAcceptanceIds: ['A1'],
          acceptanceReview: fixtureAcceptanceReview(['A1']),
          checks: [],
          knownLimits: [],
          submittedAt: new Date().toISOString(),
          verificationChecks: [
            {
              id: 'focused',
              name: 'Focused check',
              executable: process.execPath,
              argv: ['-e', 'process.exit(0)'],
              cwdRef: '.',
              timeoutMs: 5_000,
              repeatable: true,
            },
          ],
        },
      },
      context,
    });
    const checked = await runNativeCli([
      'next',
      'sdk-guard',
      '--project-root',
      projectRoot,
      '--json',
    ]);
    expect(checked.exitCode, checked.stderr).toBe(0);
    await expect(
      inspectNativeHookGuard(projectRoot, writeRequest('src/index.ts'), 'sdk-guard'),
    ).resolves.toMatchObject({ allowed: false, change: 'sdk-guard', phase: 'verify' });
    await expect(inspectNativeSdkRun(projectRoot, 'sdk-guard')).resolves.toMatchObject({
      state: { phase: 'verify' },
    });
    const sourceFile = path.join(projectRoot, 'source.ts');
    const source = 'export const value = 1;\n';
    await fs.writeFile(sourceFile, source);
    const beforeComment = await inspectNativeSdkRun(projectRoot, 'sdk-guard');
    const commentRequest = parseNativeHookRequest(
      JSON.stringify({
        tool_name: 'Edit',
        tool_input: {
          file_path: sourceFile,
          old_string: source,
          new_string: '// Explain the value.\n' + source,
        },
      }),
    );
    await expect(
      inspectNativeHookGuard(projectRoot, commentRequest, 'sdk-guard'),
    ).resolves.toMatchObject({ allowed: true, phase: 'verify' });
    expect((await inspectNativeSdkRun(projectRoot, 'sdk-guard')).run).toEqual(beforeComment.run);
    await expect(
      inspectNativeHookGuard(
        projectRoot,
        parseNativeHookRequest(
          JSON.stringify({
            tool_name: 'Edit',
            tool_input: {
              file_path: sourceFile,
              old_string: source,
              new_string: '// @ts-nocheck\n' + source,
            },
          }),
        ),
        'sdk-guard',
      ),
    ).resolves.toMatchObject({ allowed: false, phase: 'verify' });
    await expect(
      fs.readFile(path.join(paths.changesDir, 'sdk-guard', 'comet-state.yaml'), 'utf8'),
    ).resolves.toContain('phase: verify');
  });

  it('allows a configured project-local path during Native Shape', async () => {
    await writeProjectConfig(projectRoot, defaultProjectConfig('.'));
    await addHookAllowPath('docs/team-notes');
    await activeChange('shape', 'shape-allow-path');

    await expect(
      inspectNativeHookGuard(projectRoot, writeRequest('docs/team-notes/note.md')),
    ).resolves.toMatchObject({
      allowed: true,
      phase: 'shape',
      reason: expect.stringContaining('configured Hook allow path'),
    });
  });

  it('guards user-level Runtime files outside the project tree', async () => {
    await writeProjectConfig(projectRoot, defaultProjectConfig('.'));
    await activeChange('shape', 'home-runtime-guard');
    const paths = await nativeProjectPaths(projectRoot, '.');
    for (const target of [
      path.join(paths.changesRuntimeDir, 'home-runtime-guard/state.json'),
      path.join(paths.workspaceRuntimeRoot, 'state-projections/native/home-runtime-guard.json'),
    ]) {
      await expect(
        inspectNativeHookGuard(projectRoot, writeRequest(target)),
      ).resolves.toMatchObject({
        allowed: false,
        phase: 'shape',
        reason: expect.stringContaining('Runtime-owned'),
      });
    }
  });

  it('does not let the allowlist bypass Native Runtime-owned files', async () => {
    await writeProjectConfig(projectRoot, defaultProjectConfig('.'));
    await addHookAllowPath('.comet');
    await activeChange('shape', 'runtime-reserved-allow-path');

    await expect(
      inspectNativeHookGuard(projectRoot, writeRequest('.comet/runtime/extra.json')),
    ).resolves.toMatchObject({ allowed: false, phase: 'shape' });
  });

  it.each(['shape', 'verify', 'archive'] as const)(
    '%s stays neutral when a write target cannot be attributed',
    async (phase) => {
      await writeProjectConfig(projectRoot, defaultProjectConfig('.'));
      await activeChange(phase, `unknown-${phase}`);

      await expect(inspectNativeHookGuard(projectRoot, writeRequest())).resolves.toMatchObject({
        allowed: true,
        phase,
        reason: expect.stringContaining('not attributed'),
      });
    },
  );

  it('allows explicit non-write tools during a guarded phase', async () => {
    await writeProjectConfig(projectRoot, defaultProjectConfig('.'));
    await activeChange('shape', 'read-during-shape');

    await expect(inspectNativeHookGuard(projectRoot, nonWriteRequest())).resolves.toMatchObject({
      allowed: true,
      reason: 'Hook event is not a write',
    });
  });

  it('allows portable Build implementation writes while protecting Runtime-owned state', async () => {
    await writeProjectConfig(projectRoot, defaultProjectConfig('.'));
    const { paths, state } = await portableBuild('portable-build');
    const briefRef = path
      .relative(projectRoot, path.join(nativePortableChangeDir(paths, state.name), 'brief.md'))
      .replaceAll('\\', '/');
    await expect(
      inspectNativeHookGuard(projectRoot, writeRequest(briefRef, 'src/index.ts')),
    ).resolves.toMatchObject({
      allowed: false,
      reason: expect.stringContaining('separate actions'),
    });
    await expect(readNativePortableChange(paths, state.name)).resolves.toMatchObject({
      phase: 'build',
    });
    await expect(
      inspectNativeHookGuard(projectRoot, writeRequest('src/index.ts')),
    ).resolves.toMatchObject({ allowed: true, phase: 'build', change: state.name });
    const stateRef = path
      .relative(
        projectRoot,
        path.join(nativePortableChangeDir(paths, state.name), 'comet-state.yaml'),
      )
      .replaceAll('\\', '/');
    await expect(
      inspectNativeHookGuard(projectRoot, writeRequest(stateRef)),
    ).resolves.toMatchObject({ allowed: false, reason: expect.stringContaining('Runtime-owned') });
  });

  it('keeps parent Build implementation writes assigned to child changes', async () => {
    await writeProjectConfig(projectRoot, defaultProjectConfig('.'));
    const paths = await nativeProjectPaths(projectRoot, '.');
    await ensureNativeDirectories(paths);
    const branch = execFileSync('git', ['branch', '--show-current'], {
      cwd: projectRoot,
      encoding: 'utf8',
    }).trim();
    await createNativePortableChange({
      paths,
      name: 'portable-parent',
      language: 'en',
      workspaceBinding: {
        isolation: 'current',
        changeBranch: branch,
        targetBranch: branch,
