  it('rejects startup receipts that are stale for the current attempt or candidate', async () => {
    const dispatched = await dispatchVerifier('receipt-stale');
    const candidateId = dispatched.state.builder_handoff!.candidate_id;

    await expect(
      applyNativeRunnerInput({
        paths,
        name: 'receipt-stale',
        input: {
          kind: 'verifier-started',
          candidateId,
          verifierExecutionRef: 'not-the-current-execution',
        },
        maxVerifyFailures: 5,
      }),
    ).rejects.toThrow(/stale|active/iu);

    await expect(
      applyNativeRunnerInput({
        paths,
        name: 'receipt-stale',
        input: {
          kind: 'verifier-started',
          candidateId: 'another-candidate',
          verifierExecutionRef: dispatched.verifierDispatch!.verifierExecutionRef,
        },
        maxVerifyFailures: 5,
      }),
    ).rejects.toThrow(/stale|active/iu);

    const status = await inspectNativePortableStatus({ paths, name: 'receipt-stale' });
    expect(status.localExecution.verifierStartup?.confirmation).toBe('unconfirmed');
  });

  it('parses exactly the verifier-started input shape', () => {
    expect(
      parseNativeRunnerInput({
        kind: 'verifier-started',
        candidateId: 'candidate',
        verifierExecutionRef: 'skill-coordinated:verifier:1',
      }),
    ).toEqual({
      kind: 'verifier-started',
      candidateId: 'candidate',
      verifierExecutionRef: 'skill-coordinated:verifier:1',
    });
    expect(() =>
      parseNativeRunnerInput({
        kind: 'verifier-started',
        candidateId: 'candidate',
        verifierExecutionRef: 'skill-coordinated:verifier:1',
        extra: true,
      }),
    ).toThrow();
    expect(() =>
      parseNativeRunnerInput({ kind: 'verifier-started', candidateId: 'candidate' }),
    ).toThrow();
  });

  it('surfaces the unconfirmed state in the human summary and recovery message', async () => {
    const dispatched = await dispatchVerifier('receipt-recovery');
    const envelopeRecord = (confirmation: 'unconfirmed' | 'confirmed') => ({
      continuation: {
        change: 'receipt-recovery',
        phase: 'verify',
        status: 'active',
        disposition: 'continue' as const,
        commandArgs: ['comet', 'native', 'next'],
        userCommunication: { required: false, message: null, agentInstruction: 'Keep waiting.' },
      },
      localExecution: { verifierStartup: { confirmation } },
    });
    expect(deriveNativeOutputEnvelope(envelopeRecord('unconfirmed'))?.summary).toContain(
      'has not confirmed startup',
    );
    expect(deriveNativeOutputEnvelope(envelopeRecord('confirmed'))?.summary).not.toContain(
      'has not confirmed startup',
    );

    const unconfirmed = await recoverNativePortableChange({
      paths,
      name: 'receipt-recovery',
    });
    expect(unconfirmed).toMatchObject({ action: 'await-user', reason: 'execution-active' });
    expect(unconfirmed.message).toContain('never confirmed startup');

    await applyNativeRunnerInput({
      paths,
      name: 'receipt-recovery',
      input: {
        kind: 'verifier-started',
        candidateId: dispatched.state.builder_handoff!.candidate_id,
        verifierExecutionRef: dispatched.verifierDispatch!.verifierExecutionRef,
      },
      maxVerifyFailures: 5,
    });
    const confirmed = await recoverNativePortableChange({
      paths,
      name: 'receipt-recovery',
    });
    expect(confirmed.message).not.toContain('never confirmed startup');
  });
});

import { resolveWorkspaceRuntimeRootSync } from '../../../domains/workflow-contract/workspace-runtime.js';
import { execFileSync, spawnSync } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { fixtureAcceptanceReview } from '../../helpers/native-builder-acceptance-review.js';
import {
  defaultProjectConfig,
  writeProjectConfig,
} from '../../../domains/comet-native/native-config.js';

const runtime = path.resolve('assets/skills/comet-native/scripts/comet-native-runtime.mjs');
const router = path.resolve('assets/skills/comet/scripts/comet-hook-router.mjs');

describe('packaged Runtime issue regressions', () => {
  let root: string;
  let external: string;
  let sequence: number;
  const name = 'issue-runtime';
  function invoke(args: string[]) {
    const result = spawnSync(
      process.execPath,
      [runtime, ...args, '--project-root', root, '--json'],
      { encoding: 'utf8', timeout: 60_000, windowsHide: true },
    );
    expect(result.error).toBeUndefined();
    const output = JSON.parse(result.stdout);
    expect(result.status).toBe(output.exitCode);
    return output;
  }
  async function input(payload: unknown, inside = false) {
    const file = path.join(inside ? root : external, `input-${++sequence}.json`);
    await fs.writeFile(file, JSON.stringify(payload));
    // Retained protocol files must be as safe as files removed after consumption.
    return invoke(['next', name, '--runner-input', file]);
  }
  function handoff() {
    return {
      kind: 'builder-handoff',
      summary: 'Both fixture behaviors implemented.',
      addressed_acceptance_ids: ['A1', 'A2'],
      acceptance_review: fixtureAcceptanceReview(['A1', 'A2']),
      checks: [],
      known_limits: [],
    };
  }
  beforeEach(async () => {
    root = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'comet-packaged-issues-')));
    external = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-packaged-input-'));
    sequence = 0;
    execFileSync('git', ['init'], { cwd: root, stdio: 'ignore' });
    await fs.writeFile(path.join(root, 'source.txt'), 'Both fixture behaviors implemented.\n');
    execFileSync('git', ['add', 'source.txt'], { cwd: root, stdio: 'ignore' });
    execFileSync(
      'git',
      [
        '-c',
        'user.name=Fixture',
        '-c',
        'user.email=fixture@example.invalid',
        'commit',
        '-m',
        'fixture',
      ],
      { cwd: root, stdio: 'ignore' },
    );
    expect(invoke(['new', name, '--runtime', 'compat']).exitCode).toBe(0);
    const config = defaultProjectConfig('docs', 'en');
    await writeProjectConfig(root, {
      ...config,
      native: { ...config.native, document_writes: 'revert' },
    });
    const change = path.join(root, 'docs/comet/changes', name);
    await fs.writeFile(
      path.join(change, 'brief.md'),
      '# Outcome\nShip both fixture behaviors.\n# Scope\nBoth fixture behaviors.\n## Directory structure\n### Created\nNone.\n### Modified\nNone.\n### Deleted\nNone.\n### Not created\nNone.\n# Non-goals\nNo unrelated work.\n# Acceptance examples\n- First behavior works.\n- Second behavior works.\n# Constraints and invariants\nKeep scope fixed.\n# Decisions\nUse fixture implementation.\n# Open questions\nNone.\n# Verification expectations\nRun applicable checks.\n',
    );
    await fs.mkdir(path.join(change, 'specs/fixture'), { recursive: true });
    await fs.writeFile(
      path.join(change, 'specs/fixture/spec.md'),
      '# Fixture target\n\nThe fixture requirements are defined in brief.md.\n',
    );
    const prepared = invoke(['next', name, '--summary', 'Shape ready']);
    expect(prepared.exitCode).toBe(0);
    expect(
      invoke([
        'next',
        name,
        '--summary',
        'Confirmed',
        '--confirmed',
        '--expected-state-version',
        String(prepared.data.state.state_version),
        '--expected-action',
        'confirm-shape',
      ]).exitCode,
    ).toBe(0);
  });
  afterEach(async () => {
    await fs.rm(root, { recursive: true, force: true });
    await fs.rm(external, { recursive: true, force: true });
  });

  it('rejects incomplete Build and reuses checks across retained in-repository protocol files', async () => {
    const before = invoke(['show', name]).data.state;
    expect(
      (await input({ ...handoff(), acceptance_review: fixtureAcceptanceReview(['A1']) }, true))
        .exitCode,
    ).toBe(65);
    expect(invoke(['show', name]).data.state).toEqual(before);
    const rejectedInput = path.join(root, `input-${sequence}.json`);
    const counter = path.join(resolveWorkspaceRuntimeRootSync(root), 'count.txt');
    const plan = {
      id: 'fixture',
      name: 'Fixture',
      executable: process.execPath,
      argv: ['-e', `require('fs').appendFileSync(${JSON.stringify(counter)}, 'run\\n')`],
      cwdRef: '.',
      timeoutMs: 10_000,
      repeatable: true,
    };
    const handedOff = await input({ ...handoff(), verification_checks: [plan] }, true);
    expect(handedOff.exitCode).toBe(0);
    const d = handedOff.data.verifierDispatch;
    await fs.rm(rejectedInput);
    expect(
      await input(
        {
          kind: 'verifier-response',
          candidateId: d.candidateId,
          verifierExecutionRef: d.verifierExecutionRef,
          response: {
            kind: 'request-checks',
            iteration: d.iteration,
            attempt: d.attempt,
            checks: [plan],
          },
        },
        true,
      ),
    ).toMatchObject({
      exitCode: 0,
      data: {
        requestChecks: { reusedCheckIds: [plan.id], executedCheckIds: [] },
        continuation: { action: 'await-verifier' },
      },
    });
    expect(await fs.readFile(counter, 'utf8')).toBe('run\n');
  });

  it.each(['verify', 'archive'])(
    'preserves completed acceptance in %s for resource targets but invalidates real mixed writes',
    async (phase) => {
      expect((await input(handoff())).exitCode).toBe(0);
      const d = (await input({ kind: 'dispatch-verifier', checks: [] })).data.verifierDispatch;
      const completed = await input({
        kind: 'verifier-response',
        candidateId: d.candidateId,
        verifierExecutionRef: d.verifierExecutionRef,
        response: {
          kind: 'final-result',
          result: {
            iteration: d.iteration,
            attempt: d.attempt,
            verdict: 'pass',
            acceptance: ['A1', 'A2'].map((id) => ({
              id,
              result: 'passed',
              reason: 'Fixture observed.',
            })),
            risks: [],
            summary: 'All fixture requirements passed.',
          },
        },
      });
      expect(completed.exitCode).toBe(0);
      if (phase === 'archive')
        expect(
          invoke([
            'next',
            name,
            '--summary',
            'Accepted result',
            '--accept-result',
            '--expected-state-version',
            String(completed.data.state.state_version),
            '--expected-action',
            'accept-result',
          ]).exitCode,
        ).toBe(0);
      const before = invoke(['show', name]).data.state;
      expect(before).toMatchObject({
        phase,
        verification_result: 'pass',
        acceptance: [
          { id: 'A1', result: 'passed' },
          { id: 'A2', result: 'passed' },
        ],
      });
      function hook(event: unknown, expectedStatus = 0) {
        const result = spawnSync(
          process.execPath,
          [router, '--platform', 'oh-my-pi', '--project-root', root],
          {
            cwd: root,
            input: JSON.stringify(event),
            encoding: 'utf8',
            timeout: 30_000,
            windowsHide: true,
          },
        );
        expect(result.status, result.stderr).toBe(expectedStatus);
      }
      hook({
        tool_input: { targets: ['agent:/Main', 'proc:/verify-server/kill', 'xd:/report_issue'] },
      });
      hook({ tool_name: 'write', tool_input: { path: 'agent:/Main' } });
      expect(invoke(['show', name]).data.state).toEqual(before);
      hook(
        {
          tool_name: 'write',
          tool_input: { targets: ['file://%broken', 'agent:/Main', 'src/new-file.ts'] },
        },
        phase === 'verify' ? 2 : 0,
      );
      expect(invoke(['show', name]).data.state).toMatchObject(
        phase === 'verify'
          ? { phase: 'verify' }
          : {
              phase: 'build',
              verification_result: 'pending',
              acceptance: [
                { id: 'A1', result: 'pending' },
                { id: 'A2', result: 'pending' },
              ],
            },
      );
    },
  );
});

import { describe, expect, it } from 'vitest';
import { isNativeOrdinaryCommentEdit } from '../../../domains/comet-native/native-source-comments.js';

describe('Native ordinary source comments', () => {
  it.each([
    'main.js',
    'main.ts',
    'main.jsx',
    'main.tsx',
    'main.mjs',
    'main.cjs',
    'main.mts',
    'main.cts',
  ])('recognizes ordinary comments in %s', (file) => {
    const source =
      file === 'main.cjs'
        ? 'module.exports.value = "// this is a string";\n'
        : 'export const value = "// this is a string";\n';
    expect(
      isNativeOrdinaryCommentEdit(file, source, '// 中文说明\n' + source + '/* More detail. */\n'),
    ).toBe(true);
  });
  it.each([
    ['export const value = 1;', 'export const value = 2;'],
    ['export const value = "// old";', 'export const value = "// new";'],
    ['const value = `// old`;', 'const value = `// new`;'],
    ['function f() { return 1; }', 'function f() { return /*\n*/ 1; }'],
    ['const a = 1;', '// @ts-nocheck\nconst a = 1;'],
    ['const a = 1;', '// eslint-disable-next-line\nconst a = 1;'],
    ['const a = f();', 'const a = /* #__PURE__ */ f();'],
    ['const a = f();', '/* istanbul ignore next */ const a = f();'],
    ['const a = 1;', 'const a = 1;\n//# sourceURL=a.js'],
    ['const a = 1;', '/*:: type A = number */\nconst a = 1;'],
    ['const a = 1;', 'const a = ;'],
    ['const a = /hello/;', 'const a = /world/;'],
  ])('keeps executable syntax and tool directives bound (%s)', (before, after) => {
    expect(isNativeOrdinaryCommentEdit('main.ts', before, after)).toBe(false);
  });
  it('fails closed for unsupported languages and mixed changes', () => {
    expect(isNativeOrdinaryCommentEdit('main.py', 'value = 1\n', '# detail\nvalue = 1\n')).toBe(
      false,
    );
    expect(isNativeOrdinaryCommentEdit('main.ts', 'const a = 1;', '// detail\nconst a = 2;')).toBe(
      false,
    );
  });
  it('keeps JSX text and TypeScript types bound', () => {
    expect(
      isNativeOrdinaryCommentEdit(
        'main.tsx',
        'const a = <div>one</div>;',
        'const a = <div>two</div>;',
      ),
    ).toBe(false);
    expect(
      isNativeOrdinaryCommentEdit('main.ts', 'const a: number = 1;', 'const a: any = 1;'),
    ).toBe(false);
  });
});

